{"hypotheses": [
  {
    "name": "Organizational Capital in Inefficient Markets",
    "mechanism": "Firms with high organizational capital (OrgCap) but underappreciated by analysts (negative AnalystRevision) may be systematically undervalued in less informationally efficient markets. Combining OrgCap with negative AnalystRevision isolates firms where market underreaction to organizational investments is likely strongest, producing a premium distinct from either alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": -1.0, "primitive": "AnalystRevision"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "OrgCap", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.70,
    "expected_decay_half_life_months": 48
  },

  {
    "name": "Mispriced Intangible Growth under Credit Frictions",
    "mechanism": "When credit conditions tighten (TERM_SPREAD_NEGATIVE), the market tends to overpenalize high intangible asset growth (IntanBM) combined with low external financing (NetEquityFinance), creating opportunities as these firms are less reliant on outside capital and intangibles are harder to value.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "IntanBM"},
        {"weight": -1.0, "primitive": "NetEquityFinance"},
        {"weight": 0.5, "primitive": "RDcap"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 36
  },

  {
    "name": "Customer Dominance and Supply Chain Overreaction",
    "mechanism": "Stocks with strong customer momentum (iomom_cust) but negative supplier momentum (iomom_supp) are likely to benefit from demand-pull dynamics overlooked by the market, especially when coupled with high Industry concentration (Herf). This reflects pricing power and endogenous supply chain feedback.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": -1.0, "primitive": "iomom_supp"},
        {"weight": 0.5, "primitive": "Herf"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "correlation", "primitive": "iomom_cust", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": 30
  },

  {
    "name": "Profit Quality under Idiosyncratic Volatility",
    "mechanism": "Firms with high operating profitability (OperProf) but elevated idiosyncratic volatility (IdioVol3F) are often shunned due to perceived risk, but the market overdiscounts, especially when paired with stable earnings consistency (EarningsConsistency), yielding a premium for 'misunderstood quality'.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": -0.5, "primitive": "IdioVol3F"},
        {"weight": 0.5, "primitive": "EarningsConsistency"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 54
  },

  {
    "name": "Analyst Disagreement and Post-Earnings Drift",
    "mechanism": "Stocks with high earnings forecast dispersion (ForecastDispersion) but also strong recent announcement returns (AnnouncementReturn) exhibit persistent post-earnings drift, amplified by short-term uncertainty as analysts disagree about implications of recent good news.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": 1.0, "primitive": "AnnouncementReturn"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "correlation", "primitive": "AnnouncementReturn", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "mega", "direction": "weaker"}
    ],
    "expected_annualized_sharpe": 0.50,
    "expected_decay_half_life_months": 24
  },

  {
    "name": "Ownership Breadth and Option Activity",
    "mechanism": "Stocks with narrow breadth of ownership (DelBreadth) but high option volume relative to shares (OptionVolume1) are likely to reflect hidden informed trading and impending re-rating, as institutional attention lags option market signals.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "DelBreadth"},
        {"weight": 1.0, "primitive": "OptionVolume1"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "DelBreadth", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.58,
    "expected_decay_half_life_months": 18
  },

  {
    "name": "Post-IPO Illiquidity Pricing",
    "mechanism": "Firms recently post-IPO (AgeIPO) with high Amihud illiquidity (Illiquidity) but low institutional turnover (RIO_Turnover) trade at a discount due to persistent liquidity risk and slow institutional participation, enabling a premium for patient investors.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AgeIPO"},
        {"weight": 1.0, "primitive": "Illiquidity"},
        {"weight": -0.5, "primitive": "RIO_Turnover"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 60
  },

  {
    "name": "Tax Avoidance and Seasonality Interaction",
    "mechanism": "Firms with high taxable income to income (Tax) and strong return seasonality (MomSeason) benefit from systematic underpricing around fiscal calendar effects, as investors underreact to recurring tax-driven earnings management.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Tax"},
        {"weight": 1.0, "primitive": "MomSeason"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "MomSeason", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "large", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.53,
    "expected_decay_half_life_months": 36
  }
]}
